import{_ as e,o as n,c as t,a0 as r}from"./chunks/framework.D7EjqxMK.js";const g=JSON.parse('{"title":"确定性执行 Plan→Commit 架构","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/04_工程实践/03_确定性执行Plan→Commit架构.md","filePath":"06-agent/04_工程实践/03_确定性执行Plan→Commit架构.md"}'),i={name:"06-agent/04_工程实践/03_确定性执行Plan→Commit架构.md"};function o(l,a,s,c,p,m){return n(),t("div",null,[...a[0]||(a[0]=[r(`<h1 id="确定性执行-plan→commit-架构" tabindex="-1">确定性执行 Plan→Commit 架构 <a class="header-anchor" href="#确定性执行-plan→commit-架构" aria-label="Permalink to &quot;确定性执行 Plan→Commit 架构&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块四 · 04_工程实践 · 第 3 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：Agent 工程化</p></blockquote><hr><h2 id="_1-核心问题" tabindex="-1">1. 核心问题 <a class="header-anchor" href="#_1-核心问题" aria-label="Permalink to &quot;1. 核心问题&quot;">​</a></h2><p>传统 Agent 的风险：</p><ul><li>不可预测的输出</li><li>无法审计的操作</li><li>不可逆的副作用</li><li>权限越界</li></ul><h3 id="plan→commit-架构" tabindex="-1">Plan→Commit 架构 <a class="header-anchor" href="#plan→commit-架构" aria-label="Permalink to &quot;Plan→Commit 架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plan→Commit:</span></span>
<span class="line"><span>用户输入 → LLM(Plan) → 生成操作清单 → 系统(Commit) → 执行 → 结果</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>            安全护栏 + 幂等保证 + 审计日志</span></span></code></pre></div><p><strong>核心理念</strong>：让 LLM 负责 Plan（提出方案），让系统负责 Commit（确定性执行），将模型的不确定性&quot;关进笼子&quot;。<a href="https://notes.muthu.co/2026/03/receding-horizon-planning-and-plan-commitment-in-agent-reasoning-loops/" target="_blank" rel="noreferrer">来源: 技术栈 - Receding Horizon Planning and Plan Commitment</a></p><hr><h2 id="_2-planner-executor-pattern" tabindex="-1">2. Planner + Executor Pattern <a class="header-anchor" href="#_2-planner-executor-pattern" aria-label="Permalink to &quot;2. Planner + Executor Pattern&quot;">​</a></h2><p>将 Agent 的规划层和执行层分离，是构建可靠 Agent 的核心架构模式。<a href="https://blogs.utilia.dev/planner-executor-pattern-architecting-reliable-agents" target="_blank" rel="noreferrer">来源: Utilia - Planner + Executor Pattern</a></p><hr><h2 id="_3-参考资料" tabindex="-1">3. 参考资料 <a class="header-anchor" href="#_3-参考资料" aria-label="Permalink to &quot;3. 参考资料&quot;">​</a></h2><ul><li><a href="https://notes.muthu.co/2026/03/receding-horizon-planning-and-plan-commitment-in-agent-reasoning-loops/" target="_blank" rel="noreferrer">Receding Horizon Planning and Plan Commitment in Agent Reasoning Loops</a></li><li><a href="https://blogs.utilia.dev/planner-executor-pattern-architecting-reliable-agents" target="_blank" rel="noreferrer">Planner + Executor Pattern — Architecting Reliable Agents</a></li><li><a href="https://renezander.com/guides/production-ai-agent-architecture/" target="_blank" rel="noreferrer">Production AI Agent Architecture: Patterns That Actually Ship</a></li><li><a href="https://koder.ai/blog/designing-agentic-systems-that-dont-collapse-production" target="_blank" rel="noreferrer">Designing Agentic Systems That Don&#39;t Collapse in Production</a></li></ul>`,15)])])}const d=e(i,[["render",o]]);export{g as __pageData,d as default};
